package com.fooddelivery.order.service;import java.util.*;import org.springframework.stereotype.Service;import com.fasterxml.jackson.databind.ObjectMapper;import com.fooddelivery.order.entity.CustomerOrder;import com.fooddelivery.order.dto.OrderRequest;import com.fooddelivery.order.repository.OrderRepository;import com.fooddelivery.order.client.*;import com.fooddelivery.order.dto.PaymentRequest;@Service public class OrderService{private final OrderRepository r;private final RestaurantClient restaurant;private final PaymentClient payment;private final ObjectMapper mapper=new ObjectMapper();public OrderService(OrderRepository r,RestaurantClient rc,PaymentClient pc){this.r=r;restaurant=rc;payment=pc;}public CustomerOrder create(OrderRequest q){restaurant.get(q.getRestaurantId());try{CustomerOrder o=new CustomerOrder();o.setUserId(q.getUserId());o.setRestaurantId(q.getRestaurantId());o.setItemsJson(mapper.writeValueAsString(q.getItems()));o.setTotalAmount(q.getTotalAmount());o.setStatus("PENDING_PAYMENT");o=r.save(o);Map<String,Object> p=payment.pay(new PaymentRequest(o.getId(),o.getTotalAmount()));o.setStatus("SUCCESS".equals(p.get("status"))?"CONFIRMED":"PAYMENT_FAILED");return r.save(o);}catch(Exception e){throw new IllegalStateException("Unable to create order",e);}}public List<CustomerOrder> byUser(Long id){return r.findByUserId(id);}public CustomerOrder get(Long id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Order not found"));}}
